function build_deltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const item = multiset_diff(before.item, after.item);
  const ordinal_sorted = multiset_diff(before.ordinal_sorted, after.ordinal_sorted);
  return {
    rels: [
      { rel: "item", add: item.add, del: item.del },
      { rel: "ordinal_sorted", add: ordinal_sorted.add, del: ordinal_sorted.del },
    ],
    carry_pending: false,
  };
}

